SELECT json_build_object(
  'column_acls', (SELECT json_agg(json_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'acl',(SELECT json_agg(json_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)) FROM aclexplode(a.attacl) x))) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','app_private') AND a.attacl IS NOT NULL),
  'schema_acls', (SELECT json_agg(json_build_object('name', n.nspname, 'acl', (SELECT json_agg(json_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)) FROM aclexplode(COALESCE(n.nspacl,acldefault('n',n.nspowner))) x))) FROM pg_namespace n WHERE n.nspname IN ('public','app_private')),
  'tables', (SELECT json_agg(json_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'columns',(SELECT json_agg(json_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','app_private') AND c.relkind='r'),
  'sequences', (SELECT json_agg(json_build_object('schema',n.nspname,'name',c.relname,'type',format_type(s.seqtypid,NULL),'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle,'owned_table',own.relname,'owned_column',a.attname,'dependency_type',d.deptype)) FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_depend d ON d.objid=c.oid AND d.classid='pg_class'::regclass AND d.refclassid='pg_class'::regclass AND d.deptype IN ('a','i') LEFT JOIN pg_class own ON own.oid=d.refobjid LEFT JOIN pg_attribute a ON a.attrelid=d.refobjid AND a.attnum=d.refobjsubid WHERE n.nspname IN ('public','app_private')),
  'constraints', (SELECT json_agg(json_build_object('schema',n.nspname,'table',c.relname,'name',co.conname,'kind',co.contype,'definition',pg_get_constraintdef(co.oid))) FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','app_private')),
  'indexes', (SELECT json_agg(json_build_object('definition',pg_get_indexdef(i.indexrelid))) FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','app_private') AND NOT EXISTS (SELECT 1 FROM pg_constraint co WHERE co.conindid=i.indexrelid)),
  'functions', (SELECT json_agg(json_build_object('schema',n.nspname,'name',p.proname,'signature',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'acl', (SELECT json_agg(json_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)) FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) x))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','app_private') AND p.prokind='f' AND NOT EXISTS (SELECT 1 FROM pg_depend dep WHERE dep.objid=p.oid AND dep.classid='pg_proc'::regclass AND dep.deptype='e')),
  'views', (SELECT json_agg(json_build_object('schema',n.nspname,'name',c.relname,'definition',pg_get_viewdef(c.oid,true),'options',c.reloptions,'dependencies',(SELECT json_agg(DISTINCT rn.nspname||'.'||rc.relname) FROM pg_rewrite rw JOIN pg_depend d ON d.classid='pg_rewrite'::regclass AND d.objid=rw.oid JOIN pg_class rc ON rc.oid=d.refobjid JOIN pg_namespace rn ON rn.oid=rc.relnamespace WHERE rw.ev_class=c.oid AND rc.relkind='v' AND rc.oid<>c.oid AND rn.nspname IN ('public','app_private')))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','app_private') AND c.relkind='v'),
  'policies', (SELECT json_agg(json_build_object('schema',n.nspname,'table',c.relname,'name',p.polname,'permissive',p.polpermissive,'command',p.polcmd,'roles',(SELECT json_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END) FROM unnest(p.polroles) r),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','app_private','storage')),
  'triggers', (SELECT json_agg(json_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'schema',n.nspname,'table',c.relname,'name',t.tgname)) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE NOT t.tgisinternal AND n.nspname IN ('public','app_private','auth') AND pn.nspname IN ('public','app_private')),
  'relation_acls', (SELECT json_agg(json_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'acl',(SELECT json_agg(json_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)) FROM aclexplode(COALESCE(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner))) x))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','app_private') AND c.relkind IN ('r','v','S')),
  'enums', (SELECT json_agg(json_build_object('schema',n.nspname,'name',t.typname,'values',(SELECT json_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid))) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN ('public','app_private') AND t.typtype='e'),
  'extensions', (SELECT json_agg(json_build_object('name',e.extname,'schema',n.nspname)) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname<>'plpgsql'),
  'default_acls', (SELECT json_agg(json_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'acl',(SELECT json_agg(json_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)) FROM aclexplode(d.defaclacl) x))) FROM pg_default_acl d JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname IN ('public','app_private')),
  'buckets', (SELECT json_agg(json_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) FROM storage.buckets WHERE id IN ('avatars','musician_backgrounds'))
) AS schema_snapshot;
